# FIXED FILE: do not edit. Generated by bin/adding_method/add_method.py.
#
# The MESSI output contract for R methods. Everything messi_run.R writes goes
# through these validators, and so does `add_method.py check`.
# Base R only: no Bioconductor, so the self-check runs anywhere.

RESULT_COLUMNS <- c("sample_name", "y", "phat", "method_name", "dataset", "fold")
FEATURE_COLUMNS <- c("feature", "view", "coef", "method", "dataset_name")
FEATURE_INPUT_COLUMNS <- c("feature", "view", "coef")
HYPERPARAMETER_FIELDS <- c("dataset", "method", "analysis_stage", "parameters")
TREATMENTS <- c("tuned", "fixed", "default", "data-derived")
PHAT_DIGITS <- 3

contract_fail <- function(where, got, expected) {
  stop(sprintf("CONTRACT ERROR in %s\n  got:      %s\n  expected: %s", where, got, expected),
       call. = FALSE)
}

describe <- function(x) {
  if (is.null(x)) return("NULL")
  if (is.data.frame(x)) {
    return(sprintf("a data.frame with %d rows and columns: %s", nrow(x),
                   paste(colnames(x), collapse = ", ")))
  }
  if (is.matrix(x)) return(sprintf("a %s matrix of %d rows and %d columns", typeof(x), nrow(x), ncol(x)))
  if (is.factor(x)) return(sprintf("a factor of length %d", length(x)))
  if (is.atomic(x)) return(sprintf("a %s vector of length %d", typeof(x), length(x)))
  sprintf("an object of class '%s'", paste(class(x), collapse = "/"))
}

# Loads <method>_core.R into its own environment and checks the three functions exist.
load_core <- function(script_dir, method) {
  core_path <- file.path(script_dir, paste0(method, "_core.R"))
  if (!file.exists(core_path)) {
    stop("Cannot find the core file: ", core_path, call. = FALSE)
  }
  core <- new.env(parent = globalenv())
  sys.source(core_path, envir = core)
  for (fn in c("fit", "predict_proba", "feature_weights")) {
    if (!exists(fn, envir = core, inherits = FALSE) || !is.function(core[[fn]])) {
      contract_fail(basename(core_path),
                    sprintf("no function called %s()", fn),
                    "the file defines fit(), predict_proba() and feature_weights()")
    }
  }
  core
}

# The plain data handed to the developer: X is a named list of samples x features
# numeric matrices with identical row names, y an integer 0/1 vector named by sample.
validate_plain_data <- function(data, where) {
  X <- data$X
  y <- data$y
  if (!is.list(X) || length(X) == 0 || is.null(names(X)) || any(names(X) == "")) {
    contract_fail(where, describe(X), "a named, non-empty list of views")
  }
  samples <- rownames(X[[1]])
  if (is.null(samples) || anyDuplicated(samples) > 0) {
    contract_fail(where, "missing or duplicated sample names", "unique row names on every view")
  }
  for (view in names(X)) {
    m <- X[[view]]
    if (!is.matrix(m) || !is.numeric(m)) {
      contract_fail(where, sprintf("view '%s' is %s", view, describe(m)), "a numeric matrix")
    }
    if (!identical(rownames(m), samples)) {
      contract_fail(where, sprintf("view '%s' has different samples or sample order", view),
                    "the same row names, in the same order, on every view")
    }
    if (is.null(colnames(m)) || anyDuplicated(colnames(m)) > 0) {
      contract_fail(where, sprintf("view '%s' has missing or duplicated feature names", view),
                    "unique column names")
    }
  }
  if (length(y) != length(samples) || !all(y %in% c(0L, 1L))) {
    contract_fail(where, sprintf("y is %s", describe(y)),
                  sprintf("%d labels, each 0 or 1", length(samples)))
  }
  invisible(data)
}

validate_model <- function(model) {
  if (is.null(model)) {
    contract_fail("fit()", "NULL", "any object holding the fitted model")
  }
  invisible(model)
}

# Returns the scores as an unnamed numeric vector.
validate_predictions <- function(phat, samples) {
  where <- "predict_proba()"
  expected <- sprintf("a numeric vector of %d positive-class scores in [0, 1], one per row of X_test, in the same order",
                      length(samples))
  if (is.null(phat) || is.list(phat) && !is.data.frame(phat)) contract_fail(where, describe(phat), expected)
  if (is.data.frame(phat) || is.matrix(phat)) {
    if (ncol(phat) != 1) {
      contract_fail(where, paste0(describe(phat), ". Return only the column with the probability of class 1"), expected)
    }
    labels <- rownames(phat)
    phat <- if (is.data.frame(phat)) phat[[1]] else phat[, 1]
    names(phat) <- labels
  }
  if (!is.numeric(phat)) contract_fail(where, describe(phat), expected)
  if (length(phat) != length(samples)) contract_fail(where, describe(phat), expected)
  labels <- names(phat)
  if (!is.null(labels) && !identical(as.character(labels), as.character(samples)) &&
      !identical(as.character(labels), as.character(seq_along(samples)))) {
    contract_fail(where, "a vector whose names do not match the test sample names in order",
                  "names equal to rownames(X_test[[1]]), or no names: use unname()")
  }
  phat <- as.numeric(phat)
  if (any(is.na(phat))) {
    contract_fail(where, sprintf("%d NA or NaN values out of %d", sum(is.na(phat)), length(phat)), expected)
  }
  if (any(!is.finite(phat)) || any(phat < 0) || any(phat > 1)) {
    contract_fail(where, sprintf("values from %g to %g", min(phat), max(phat)),
                  paste0(expected, ". The metrics threshold phat and compute a log loss, so raw scores must be turned into probabilities"))
  }
  phat
}

# Returns a data.frame(feature, view, coef).
validate_features <- function(table, X) {
  where <- "feature_weights()"
  expected <- "a data.frame with columns feature, view, coef and at least one row"
  if (!is.data.frame(table)) contract_fail(where, describe(table), expected)
  missing_cols <- setdiff(FEATURE_INPUT_COLUMNS, colnames(table))
  if (length(missing_cols) > 0) {
    contract_fail(where, paste0(describe(table), ". Missing: ", paste(missing_cols, collapse = ", ")), expected)
  }
  if (nrow(table) == 0) contract_fail(where, "a table with 0 rows", expected)
  out <- data.frame(feature = as.character(table$feature), view = as.character(table$view),
                    stringsAsFactors = FALSE)
  if (!is.numeric(table$coef)) {
    contract_fail(where, sprintf("column coef is %s", describe(table$coef)), "numeric coef")
  }
  out$coef <- as.numeric(table$coef)
  if (any(is.na(out$feature)) || any(is.na(out$view))) {
    contract_fail(where, "NA in column feature or view", "no missing feature or view names")
  }
  if (any(!is.finite(out$coef))) {
    contract_fail(where, sprintf("%d NA, NaN or infinite values in column coef", sum(!is.finite(out$coef))),
                  "finite coef values. Use 0 for a feature with no weight")
  }
  unknown <- setdiff(unique(out$view), names(X))
  if (length(unknown) > 0) {
    contract_fail(where, paste0("unknown views: ", paste(unknown, collapse = ", ")),
                  paste0("views from: ", paste(names(X), collapse = ", ")))
  }
  for (view in unique(out$view)) {
    bad <- setdiff(out$feature[out$view == view], colnames(X[[view]]))
    if (length(bad) > 0) {
      contract_fail(where,
                    sprintf("%d features not in view '%s', such as '%s'", length(bad), view, bad[1]),
                    "feature names exactly as in colnames(X_train[[view]])")
    }
  }
  if (anyDuplicated(out[, c("feature", "view")]) > 0) {
    contract_fail(where, "duplicated feature and view pairs", "one row per feature within a view")
  }
  out
}

# The table that combine_tables.R and the metrics scripts read.
build_result_table <- function(phat, samples, y, method, dataset, fold) {
  table <- data.frame(sample_name = as.character(samples), y = as.integer(y),
                      phat = round(phat, PHAT_DIGITS), method_name = method,
                      dataset = dataset, fold = fold, stringsAsFactors = FALSE)
  validate_result_table(table, samples)
  table
}

validate_result_table <- function(table, samples) {
  where <- "the result table"
  if (!identical(colnames(table), RESULT_COLUMNS)) {
    contract_fail(where, paste(colnames(table), collapse = ", "), paste(RESULT_COLUMNS, collapse = ", "))
  }
  if (nrow(table) != length(samples) || !identical(as.character(table$sample_name), as.character(samples))) {
    contract_fail(where, sprintf("%d rows that do not match the test samples", nrow(table)),
                  sprintf("one row for each of the %d test samples", length(samples)))
  }
  if (!all(table$y %in% c(0L, 1L))) contract_fail(where, "y values other than 0 and 1", "y is 0 or 1")
  if (!is.numeric(table$phat) || any(is.na(table$phat))) {
    contract_fail(where, "non-numeric or missing phat", "numeric phat without NaN")
  }
  invisible(table)
}

# The table that merge_selected_features.R reads.
build_feature_table <- function(features, method, dataset) {
  table <- data.frame(feature = features$feature, view = features$view, coef = features$coef,
                      method = method, dataset_name = dataset, stringsAsFactors = FALSE)
  if (!identical(colnames(table), FEATURE_COLUMNS)) {
    contract_fail("the feature table", paste(colnames(table), collapse = ", "),
                  paste(FEATURE_COLUMNS, collapse = ", "))
  }
  table
}

# The record that merge_selected_hyperparameters.py reads.
# hyperparameters is the optional HYPERPARAMETERS list of the core file: plain
# values are recorded as "fixed"; use list(value = ..., treatment = ...) otherwise.
build_hyperparameter_record <- function(hyperparameters, method, dataset, seed) {
  parameters <- list()
  for (name in names(hyperparameters)) {
    item <- hyperparameters[[name]]
    if (!(is.list(item) && all(c("value", "treatment") %in% names(item)))) {
      item <- list(value = item, treatment = "fixed")
    }
    if (!(item$treatment %in% TREATMENTS)) {
      contract_fail("HYPERPARAMETERS", sprintf("treatment '%s' for %s", item$treatment, name),
                    paste0("one of: ", paste(TREATMENTS, collapse = ", ")))
    }
    parameters[[name]] <- item[c("value", "treatment")]
  }
  parameters$seed <- list(value = seed, treatment = "data-derived")
  record <- list(run_id = paste(method, dataset, sep = "-"), dataset = dataset, method = method,
                 analysis_stage = "model_selection",
                 selection = list(strategy = "fit_on_all_samples"),
                 parameters = parameters)
  missing_fields <- setdiff(HYPERPARAMETER_FIELDS, names(record))
  if (length(missing_fields) > 0) {
    contract_fail("the hyperparameter record", paste(names(record), collapse = ", "),
                  paste(HYPERPARAMETER_FIELDS, collapse = ", "))
  }
  record
}

# A small JSON writer, so the wrappers need no JSON package.
to_json <- function(x) {
  if (is.null(x)) return("null")
  if (is.list(x)) {
    items <- vapply(x, to_json, "")
    if (is.null(names(x))) return(paste0("[", paste(items, collapse = ","), "]"))
    return(paste0("{", paste0(json_string(names(x)), ":", items, collapse = ","), "}"))
  }
  values <- if (is.character(x) || is.factor(x)) {
    json_string(as.character(x))
  } else if (is.logical(x)) {
    tolower(as.character(x))
  } else {
    format(x, digits = 15, trim = TRUE, scientific = FALSE, drop0trailing = TRUE)
  }
  values[is.na(x)] <- "null"
  if (length(x) == 1) return(values)
  paste0("[", paste(values, collapse = ","), "]")
}

json_string <- function(x) {
  x <- gsub("\\", "\\\\", x, fixed = TRUE)
  x <- gsub("\"", "\\\"", x, fixed = TRUE)
  paste0("\"", x, "\"")
}

write_result_csv <- function(table, path) write.csv(table, path, row.names = FALSE)
write_feature_csv <- function(table, path) write.csv(table, path, row.names = FALSE)
write_hyperparameter_json <- function(record, path) writeLines(to_json(record), path)

# Same rule as get_seed() in the existing R methods.
seed_from_label <- function(label) sum(utf8ToInt(label))
